    "A deep hollow hidden behind a vast waterfall.": "巨大瀑布后隐藏的深洞。",
    "A device that looks a little like a waterwheel, with seven shelves to switch between books at your leisure.": "一个有点像水车的装置，有七个架子可在闲暇时切换书籍。",
    "A dwarp can hear the drip of water through 100 feet of solid rock.": "矮侏可以听到100英尺坚固岩石中水的滴落。",
    "A flash of pure white light.": "纯白光的闪烁。",
    "A floating orb of unstable void magic.": "一个不稳定虚空魔法的漂浮球体。",
    "A gathering of like-minded nature appreciators in the wilderness.": "一群志同道合的自然爱好者在旷野中的聚集。",
    "A ghostly wisp of air.": "一道幽灵般的空气精灵。",
    "A ghostly wisp of summoned air.": "一道被召唤的空气幽灵。",
    "A gigantic reptile plows its jaw through the earth to eat.": "一个巨大的爬行动物用它的下颚犁过泥土来吃。",
    "A gleaming orb of light.": "一个闪烁的光球。",
    "A hidden pocket of the plane of ash and fire.": "灰烬与火焰位面的隐秘空间。",
    "A lance of solid light.": "一杆固体光的长矛。",
    "A large pulse of light zips around you, mending injuries.": "一大束脉冲光在你周围飞驰，修复伤口。",
    "A level of wizardry seen only in myths, chalked up as little more than fairy tales. Yet still, you aim towards a step even further beyond.": "只在神话中见过的魔法水平，被当作童话故事。然而，你仍然向更远的前方迈步。",
    "A light in the darkness.": "黑暗中的光芒。",
    "A light in the heavens guides your way.": "天堂之光指引你的道路。",
    "A light wind steadies your nerves.": "一阵轻风稳定你的神经。",
    "A lighted tower on the shore of the ocean.": "海岸上的一座灯塔。",
    "A mage specialising in air manipulation and intuition.": "专精于气流操控与直觉的法师。",
    "A mage specialising in earth manipulation and endurance.": "专精于大地操控与持久力的法师。",
    "A mage specialising in water manipulation and adaptability.": "专精于水流操控与适应性的法师。",
    "A mastery of air.": "对空气的精通。",
    "A mastery of earth.": "对大地的精通。",
    "A mastery of fire.": "对火的精通。",
    "A mastery of light.": "对光的精通。",
    "A mastery of spirit.": "对精神的精通。",
    "A mastery of water.": "对水的精通。",
    "A multi-headed beast rears its heads from the water.": "一个多头的野兽从水中抬起它的头。",
    "A penchant for chaos.": "对混沌的偏爱。",
    "A place to meditate in solitude, deep beneath the earth.": "在地底深处独自冥想的地方。",
    "A pulse of light zips around you, mending injuries.": "一束脉冲光在你周围飞驰，修复伤口。",
    "A small corner beneath the stairs of your Master's domicile.": "你导师住所楼梯下的一个小角落。",
    "A small pulse of light zips around you, mending injuries.": "一小束脉冲光在你周围飞驰，修复伤口。",
    "A space carved from the plane of earth.": "从大地位面开凿出的空间。",
    "A spirit cloaked in noxious nether.": "一个笼罩在剧毒幽冥中的灵魂。",
    "A Spiritual Balance": "精神平衡",
    "A supreme master of earth's destructive magics.": "大地毁灭魔法的至高大师。",
    "A trinket bestowed on mages embroiled in the world's affairs.": "赐予卷入世间事务的法师们的小饰品。",
    "A vast mound of earth dedicated to occult practices.": "一个专用于神秘实践的巨大土丘。",
    "A vibrant meadow where hawthorn trees bloom and mayflowers carpet the ground. On Beltane, the old pacts loosen here first, and fae lights dance among the flowers.": "一片生机盎然的草甸，山楂树繁花盛放，五月花铺满地际。每逢贝尔坦节，古老契约最先在此松动，仙灵萤火在花间翩跹起舞。",
    "A violent burst of water.": "一阵猛烈的水爆。",
    "A warm fireplace; the more you have the more gems you require to create them.": "一个温暖的壁炉；拥有的越多，创建它们所需的宝石也越多。",
    "A wide and yawning cavern, deep beneath the earth.": "地底深处一个宽阔的大洞穴。",
    "A writhing fungus chokes the air with spores.": "扭动的真菌用孢子充斥空气。",
    "Afflict the opponent with an earthen curse, so that their bones turn into gems.": "用地之诅咒折磨对手，让他们的骨头变成宝石。",
    "After taking your savings, your new master grants you a small nook under the stairs.": "在收走你的积蓄后，你的新导师允许你住在楼梯下的一个小角落里。",
