    "airy": "通风",
    "All the air you require.": "你所需的全部空气。",
    "All your hairs feel prickly.": "你所有的汗毛都感到刺痛。",
    "An ancient magic from beyond the sea, combining spirit and blade.": "来自海外的古老魔法，融合了灵魂与剑刃。",
    "An arc of lightning flashes from the sky.": "一道闪电弧从天空闪过。",
    "An elegant latticed portal for letting in air and light.": "一个优雅的花格窗，用于通风和采光。",
    "An enveloping shroud of air and water magic to ensure you keep cool.": "一层笼罩的空气与水魔法之雾，确保你保持凉爽。",
    "An invisible spirit binds your scrolls into codices.": "一个看不见的精灵将你的卷轴装订成典籍。",
    "An onslaught of chaos drowns your foe.": "混沌的猛攻淹没你的敌人。",
    "An unending supply of air.": "源源不断的空气供应。",
    "An unstoppable force of nature, a Titan is Will incarnate.": "一股不可阻挡的自然之力，泰坦是意志的化身。",
    "Animate your shadow for a dependable ally- a risky move.": "活化你的影子成为可靠的盟友——一个冒险的举动。",
    "Ardent of nature.": "热心于自然。",
    "aylesmeade fair": "艾尔斯米德集市",
    "Balancing respectable and wicked acts, you ensure that both light and shadow can flourish without either becoming too powerful to constrain.": "平衡可敬和邪恶的行为，你可以确保光明和暗影都能蓬勃发展，而不至于任何一方过于强大而无法约束。",
    "Become one with nature.": "与自然合为一体。",
    "Become one with the wind and water.": "与风和水的合一。",
    "Befuddling Spirits": "迷惑灵魂",
    "befuddling spirits": "迷惑灵魂",
    "Bend the earth to your will.": "让大地屈从于你的意志。",
    "Benevolent to a fault, the light reveals its final secrets on your path of virtue.": "仁慈到极致，光明在你的美德之路上揭示了它最后的秘密。",
    "Beyond the sphere of the planes lies a great void. Of its powers and dangers, the books are silent.": "在位面之球之外存在着一个巨大的虚空。关于它的力量和危险，书籍缄默不语。",
    "bonfire": "营火",
    "Born under the celestial sign of earth.": "出生于大地天象之下。",
    "Born under the celestial sign of fire.": "出生于火焰天象之下。",
    "Born under the celestial sign of light.": "出生于光明天象之下。",
