    "Chaos incarnate. You can do anything!": "混沌化身。你无所不能！",
    "Chaos magic to send the gold on your ledger sheets into volatile half-states. It collapses into either multiplication or depletion on later observation.": "混沌魔法将你账簿上的金币送入不稳定的半状态。在后续观察时，它会坍缩为增殖或耗尽。",
