    "Circulate water mana in your vicinity to combat exhaustion.": "在你周围循环流水法力以对抗疲劳。",
    "Cleansing Fire": "净化之火",
    "cleansing fire": "净化之火",
    "Cleansing waters flow over you, slowly mending your wounds.": "净化之水潺潺流过你，缓慢修复你的伤口。",
    "Cleansing waters rush over you, rapidly mending your wounds.": "净化之水奔涌过你，快速修复你的伤口。",
    "Cleansing waters trickle over you, slowly mending your wounds.": "净化之水涓涓流过你，缓慢修复你的伤口。",
    "Close your eyes. Inhale. Count. Exhale. Feel the movement of the air through you, through the world.": "闭上眼睛。吸气。计数。呼气。感受空气穿过你、穿过世界的运动。",
