    "Create a herbal mixture to repair the damage in your body that living as a starving street orphan brought with it.": "制作一种草药混合物，修复作为饥饿街头孤儿的生活给你身体带来的损害。",
    "Crucial to avoid tripping over anything when the real work begins.": "在真正的工作开始前避免被任何东西绊倒是至关重要的。",
    "Dancing under the moonlight, and misleading wanderers.": "在月光下起舞，误导迷途的旅人。",
    "Day and night the dark gates stand open to all... but to return to the open air... that is the task, that is the labor.": "黑暗之门日夜为众生敞开……但若想重返人间凡尘，便是重重考验，亦是无尽修行。",
    "Defile Spirits": "亵渎灵魂",
    "defile spirits": "亵渎灵魂",
    "dew of icy fire": "冰火之露",
    "Dig out some more space behind the waterfall and raise the cliff it plunges over.": "在瀑布后面挖出更多空间，并抬高它倾泻而下的悬崖。",
    "Dig up various spots and study the earth. Surely it can't all just be dirt.": "挖掘各种地点并研究大地。它肯定不可能都只是泥土。",
    "Doubles the effectiveness of your Hearths": "使你的壁炉效果翻倍。",
    "Each spring Aylesmeade holds its fabled fair in sight of the World Tree, Aesilwyr.": "每年春天艾尔斯米德在世界树艾希尔威尔附近举办传说中的集市。",
