    "Fae lights dance among the flowers, guiding those who honor the old ways.": "仙灵萤火花间流转，引守古道、心怀敬意之人前行。",
    "Fallen from grace, once hailed as a hero. Now fully corrupted, the shadow helps you unlock secrets you thought lost to you.": "从恩典中堕落，曾被誉为英雄。现已完全腐化，暗影帮助你解锁了你以为已经失去的秘密。",
    "fazbit's hearth": "法兹比特壁炉",
    "festive fires": "节庆之火",
    "Finely carved wooden pipe. Ruminate while peering into the sunset or a fire.": "精雕细刻的木烟斗。凝视日落或火焰时沉思。",
