    "firesource": "火源泉",
    "Fix your gaze upon a single point in the center of the flame and meditate upon the hunger of fire.": "将你的目光固定在火焰中心的一个点上，冥想火焰的饥饿。",
    "Float above any cloud. Exult in the sunlight.": "漂浮在任何云层之上。在阳光下欢欣。",
    "Focus of air magic.": "大气魔法的聚焦器。",
    "Focusing on otherworldly pursuits rather than worldly concerns, you obtain surprising insights into spiritual matters. You must be tier 4 or higher.": "专注于超凡的追求而非世俗的纷扰，你获得了对精神事务的惊人洞见。你必须达到 4 阶或更高。",
    "For all the pains, cajoling spirits pays off once you see how such ethereal creatures maintain their existences.": "尽管过程痛苦，但一旦你看到这种空灵的生物如何维持它们的存在，哄骗灵魂就是值得的。",
    "Forestfire": "森林大火",
    "Forged in the hottest of fires, under the immense pressure, not even the most extraordinary smith could produce metal of such quality.": "在极炽的火焰与巨大的压力下锻造，即使是最非凡的铁匠也无法打造出如此品质的金属。",
    "foxfire": "狐火菌",
    "Gather like-minded lovers of nature to establish a permanent collective in the wilderness.": "聚集志同道合的自然爱好者，在荒野中建立一个永久集体。",
    "Gaze through the sky and discover something new in the void amidst stars.": "凝视天空，在星星之间的虚空中发现新东西。",
    "Gem imbued with raw spirit.": "充满纯粹精神的宝石。",
    "Gem imbued with the essence of air.": "充满大气精华的宝石。",
    "Gem imbued with the essence of earth.": "充满大地精华的宝石。",
    "Gem imbued with the essence of fire.": "充满火焰精华的宝石。",
    "Gem imbued with the essence of light.": "充满光明精华的宝石。",
    "Gem imbued with the essence of water.": "充满流水精华的宝石。",
    "Get some fresh air and take meticulous notes about the flora of Gorborung.": "呼吸一些新鲜空气，并细致地记录 Gorborung 的植物群。",
    "Gildella The Lighthearted": "吉尔黛拉·乐天",
    "gildella the lighthearted": "吉尔黛拉·乐天",
    "Greater Air Elemental": "高等风息元素",
    "Greater Earth Elemental": "高等大地元素",
    "Greater Fire Elemental": "高等火焰元素",
    "Greater Light Spear": "高级光矛",
    "greater light spear": "高级光矛",
    "Greater Pulsing Light": "高级脉动之光",
    "greater pulsing light": "高级脉动之光",
    "Greenwood Spirit": "绿林之魂",
    "Having shed some of the taint of your prior sinister acts, the light welcomes you back.": "在洗去了一些从前邪恶行为的污点后，光明欢迎你回来。",
    "Head to the shores that shattered the fleet of Veldran to observe and record the cycles water goes through in nature.": "前往击碎 Veldran 舰队的海岸，观察并记录水在自然界中经历的循环。",
    "Hestia's amulet throbs with a dull purple light.": "赫斯提亚的护身符发出暗淡的紫色脉冲光芒。",
    "Hold more spirits in your sway.": "在你的掌控下控制更多精灵。",
    "Holds water for washing yourself and other some such.": "盛水供你洗漱和其他用途。",
    "Hooves of flame leave lines of fire in the ground.": "火焰之蹄在地上留下火线。",
    "Imbue Gem (Air)": "灌注宝石·风息",
    "imbue gem (Air)": "灌注宝石·风息",
