    "Imbue Gem (Spirit)": "灌注宝石·灵魂",
    "imbue gem (Spirit)": "灌注宝石·灵魂",
    "Imbue Gem (Water)": "灌注宝石·流水",
    "imbue gem (Water)": "灌注宝石·流水",
    "Immortal spirits of nature, even the weakest Kell are beings to rival wizards.": "不朽的自然之灵，即使是最弱小的凯尔也足以与巫师比肩。",
    "Inner Fire": "内在之火",
    "inner fire": "内在之火",
    "Inner Light": "内在之光",
    "inner light": "内在之光",
    "Interpret the strange whisperings of spirits.": "解读灵魂的奇怪低语。",
    "Intricate patterns of light and a gentle breeze flow through its elaborate designs.": "复杂的光图案和轻柔的微风流过其精巧的设计。",
    "Invert the laws of reality within the target to create a weakness to chaos.": "颠倒目标体内现实的法则，以制造对混沌的弱点。",
    "It has wings and a halo of light.": "它有翅膀和一个光环。",
    "It is better to light one candle than to curse the darkness.": "点燃一根蜡烛总比诅咒黑暗好。",
    "It is common for powerful wizards to bind lesser spirits to perform menial tasks. These chained spirits greatly enhance your production of texts.": "强大的法师通常束缚低级灵体来执行琐碎任务。这些被束缚的灵体极大地提高了你的文本产量。",
    "It's more fire than bird.": "它更像是火而不是鸟。",
    "Its faint light stirs the restless spirits.": "它微弱的光芒扰动着不安的亡灵。",
    "Just chill underneath a waterfall.": "就在瀑布下面放松一下。",
    "Keep gazing into the center of the flame. Embrace the heat and light.": "持续凝视火焰的中心。拥抱热与光。",
    "lake of fire": "烈焰之湖",
    "Leap to the bottom of the village pond. Feel its weight. Hold your breath until you nearly drown. Become water.": "跳入村塘底部。感受它的重量。屏住呼吸直到差点淹死。成为水。",
    "Learn how to gently nudge water with your will alone. Little more than a party trick for most, it is a great tool for cleaning the mountains of dishes your master's experiments leave behind.": "学习如何仅凭意志轻轻推动水流。对大多数人来说不过是聚会把戏，但它是清理你导师实验留下的堆积如山的盘子的绝佳工具。",
