    "Need a shadowsource and a spiritsource.": "需要一个暗影源泉和一个精神源泉。",
    "Needs a firesource and a lightsource.": "需要一个火源和一个光源。",
    "Needs a watersource and a plantsource.": "需要一个水源和一个植物源泉。",
