    "Needs an earthsource and a shadowsource.": "需要地源和一个暗影源泉。",
    "Newly armed, go and win the riddling competition at the village's yearly fair.": "装备齐全后，去村庄年度集市上赢得谜语比赛。",
    "No sound except for the parting air is heard": "只听到空气被划开的声音。",
    "observing nature": "观察自然",
    "observing nature ": "观察自然：",
    "Ominous shapes drift and flow beneath the murky waters.": "不祥的形体在浑浊的水下漂流和流动。",
    "One With Nature": "与自然合一",
    "one with nature": "与自然合一",
    "Originally devised as a way to supplement labor shortages, its addictive nature has proven to be more trouble than it's worth.": "最初设计用于补充劳动力短缺，但其成瘾性已被证明弊大于利。",
    "Own a firesource and live outdoors.": "拥有一个火源并居住在户外。",
    "Palus was a mere dabbler before unearthing the remains of a Dhrozen knight. Now he leads the Barrow priests.": "帕卢斯在发掘出德罗森骑士遗骸之前只是个纯粹的涉猎者。现在他领导窟冢祭司。",
    "Plane Of Shadows": "暗影位面",
    "Plane of Shadows": "暗影位面",
    "Plane Of Spirits": "灵魂位面",
    "Plane of Spirits": "灵魂位面",
    "Ponder upon your newfound connection to the earth.": "思考你与大地的新联系。",
    "Pools of light congeal softly in the basin.": "光池在盆中轻柔凝结。",
    "Portion Of Waterbreathing": "水下呼吸药剂",
