    "Protection: Water": "防护：流水",
    "Pull small objects out of thin air.": "凭空拉出小物件。",
    "Pulsing Light": "脉动之光",
    "pulsing light": "脉动之光",
    "Question Spirits": "询问灵魂",
    "question spirits": "询问灵魂",
    "Quickly solidifies when in contact with air.": "接触空气时迅速凝固。",
    "Recruit idle spirits to play pranks on passersby.": "招募空闲的幽灵对路人恶作剧。",
    "Removes most forms of inisidious motion impairment.": "治疗大多数行动不便的症状",
    "Reshapes your body to make it ever so slightly more ideal.": "重塑你的身体，使其变得更加理想。",
    "Resistance to air-based assaults and enfeeblements.": "对基于大气的攻击和虚弱的抗性。",
    "Resistance to earth-based attacks and afflictions.": "对基于大地的攻击和折磨的抗性。",
    "Resistance to fire-based blasts and immolations.": "对基于火焰的爆炸和焚烧的抗性。",
    "Resistance to light-based rays and dazzles.": "对基于光明的射线和炫光的抗性。",
    "Resistance to nature-based thorns and toxins.": "对基于自然的荆棘和毒素的抗性。",
    "Resistance to shadow-based curses and ruins.": "对基于暗影的诅咒和毁灭的抗性。",
    "Resistance to spirit-based hexes and haunts.": "对基于精神的诅咒和困扰的抗性。",
    "Resistance to water-based barrages and detriments.": "对基于流水的弹幕和伤害的抗性。",
    "Rumors say that deep in the woods, there is a shack once inhabited by a wizard obsessed with fire. He has not been seen for years and terrible heat can be felt emanating from the place": "传闻密林深处有一间小屋，曾住着一位痴迷烈焰的法师。他已多年不见踪影，屋内却始终散发出骇人的热浪",
    "Rune etched with lines of fire.": "刻有烈焰纹路的符文",
    "Rune etched with solid air.": "刻有凝固大气的符文。",
    "Rune lined in flowing water.": "刻有流水纹路的符文。",
    "Rushlights": "灯芯草烛",
    "Ruthless as the barren earth.": "冷酷如荒芜之地。",
    "Scrupulous deeds and virtuous thoughts guide you closer to the light.": "审慎的行为和有德的思想引导你更接近光明。",
    "Sea Spirit": "海之魂",
