    "Sinister deeds unlock further secrets obscured by the shadow.": "阴险的行为解锁了被暗影遮蔽的进一步秘密。",
    "Siphoning a portion of the force used against your barrier, repair it.": "吸取一部分用于攻击你屏障的力量来修复它。",
    "Slightly better than sleeping on the floor.": "比睡地板略好一些。",
    "Sometimes lightning does strike twice.": "有时闪电确实击中两次。",
    "Spare a little candle, save some light for me.": "省下一根小蜡烛，为我留一点光。",
    "Specialized in nothing but runesmithing, they charge a more than fair price per rune stone.": "他们只专精在符文锻造上，每块符文石收费相当合理。",
