    "Spirit Sign": "灵魂印记",
    "spirit sign": "灵魂印记",
    "Spirit, as the balance point between shadow and light, presents greater insights into itself now that you have reached equilibrium. You must be tier 4 or higher.": "精神，作为暗影和光明之间的平衡点，现在你已经达到了均衡，它将展现出对自身的更深刻洞见。你必须达到 4 阶或更高。",
    "Spirits never sleep.": "精灵从不睡觉。",
    "spirits Rate: ": "灵魂速率：",
    "Spiritsource": "精神源泉",
    "spiritsource": "精神源泉",
    "Spiritual Amorality": "精神非道德",
    "Spiritual Possession": "灵魂附体",
    "spiritual possession": "灵魂附体",
    "Spiritually Balanced": "精神平衡",
    "Standing in the distant light of celestials, the mortal world seems so... Petty.": "站在天体的遥远光芒中，凡俗世界显得如此……微不足道。",
    "Star-light, Star-bright...": "星光，闪耀……",
    "Study of pure light.": "对纯粹之光的研究。",
    "Study Water Cycle": "研究水循环",
    "study water cycle": "研究水循环",
    "studying air": "研究空气",
    "studying air ": "研习风息：",
    "studying water": "研究水",
    "studying water ": "研习流水：",
    "Summon an incarnation of extreme light as an ally.": "召唤一个极致光芒的化身作为盟友。",
    "Summon an incarnation of extreme shadow as an ally.": "召唤一个极致暗影的化身作为盟友。",
    "Taint the restless dead with shadow and study their changes.": "用暗影玷污不安的亡灵并研究它们的变化。",
    "Tainted, Archon of the Void": "污者，虚空执政官",
    "Teach the spirits of water a game about freezing the villagers' hair and laundry.": "教水之精灵一个关于冻结村民头发和衣物的游戏。",
    "Temporarily increase your natural aptitude for air.": "暂时提升你对风的天赋。",
    "Temporarily increase your natural aptitude for earth.": "暂时提升你对大地的天赋。",
    "Temporarily increase your natural aptitude for fire.": "暂时提升你对火焰的天赋。",
    "Temporarily increase your natural aptitude for water.": "暂时提升你对水的天赋。",
    "The deeper woods posses many features of interest to the magical scholar. The spirits of the place make sure to keep the troublemakers out.": "密林深处藏有诸多令法师学者心驰神往的奇景，此地的灵体自会将滋事之徒隔绝在外。",
    "The earth shakes at your command.": "大地在你的命令下震动。",
    "The earth shakes beneath your enemies' feet.": "大地在你的敌人脚下震动。",
    "The fae watch from the shadows, but allow respectful gathering.": "仙灵隐于暗影之中默默注视，亦会默许心怀敬意之人采摘灵物。",
    "The final step on the twisting stairwell of apprenticeship.": "学徒螺旋阶梯的最后一步。",
    "The half-goblin Pidwig has sailed the waters around his bay for hundreds of years. In that time he has collected a myriad of interesting artifacts.": "半地精皮德维格，已在自家海湾航行了数百年之久。漫长岁月里，他收藏了数不胜数的奇珍古物。",
    "The investigation of fire.": "对火的研究。",
    "The light fantastic.": "奇妙之光。",
    "The ranks of the Kell range from the lesser Fey and forest Delki, to ancient spirits, old and indomitable.": "Kell 的等级从低阶的妖精和森林 Delki，到古老而不屈的灵魂。",
    "The ravages of nature have been collapsing parts of your structures. Time to see to that.": "自然的肆虐一直在使你的部分结构坍塌。是时候处理一下了。",
    "The serpent that grips the earth in its scales.": "用鳞片抓住大地的蛇。",
    "The shadow whispers promises of knowledge and power to you, if only you will heed the call.": "暗影向你低语着知识和力量的承诺，只要你愿意听从召唤。",
    "The sole desire of a restless spirit is to acquire company for its undeath.": "不安灵魂的唯一渴望是为其不死之身寻找同伴。",
    "The study of air.": "对空气的研究。",
    "The study of water.": "对水的研究。",
    "The void beckons. Grasp how to mould it into useful positive and negative space.": "虚空在召唤。掌握如何将其塑造成有用的正空间和负空间。",
    "The whirling chaos above the sea.": "海面上旋转的混沌。",
    "Their globed hands glow with pale, unearthly light.": "它们球状的手发出苍白、超自然的光。",
    "There's always space behind a waterfall. Your stuff lives there now.": "瀑布后面总有空间。你的东西现在住那儿了。",
    "They seem to be in good spirits": "它们似乎精神不错。",
    "Things beyond even your comprehension lair here.": "甚至超出你理解的事物在此巢穴。",
    "This will permanently lock the Waterfall and unlock a new home when completed.": "这将永久锁定瀑布并在完成后解锁新家园。",
    "Throw at an enemy and watch them ignite into a fireball.": "扔向敌人，看着他们燃成一个火球。",
    "Touching The Void": "触碰虚空",
    "touching the void": "触碰虚空",
    "Tradition tells of a spring with enchanted waters. Investigations might prove revealing.": "传说此地有一处灵泉，泉水蕴有魔力，深入探寻或许会有惊人发现。",
    "Truly, you are incorruptible, and the light recognizes the good in you.": "确实，你廉洁自守，光明认可了你内心的善良。",
    "Twin arcs of lightning flash from the sky.": "两道闪电弧从天空闪烁。",
    "Underwater, Dungeon": "水下 · 地牢场景",
    "Unlimited source of water.": "无限水源。",
    "Unlocks an ability to radically shapeshift for the duration of the season. Also allows you to find chaos gems in halloween locations.": "解锁在该季节期间彻底变形形态的能力。还允许你在万圣节地点找到混沌宝石。",
    "Unseen spirits assist you in compiling knowledge, speeding up your work.": "看不见的精灵协助你编纂知识，加快你的工作速度。",
    "Use directed gusts of wind to clear away debris and detritus, making exploration a much more profitable affair.": "使用定向阵风清除碎屑和残渣，使探索更有利可图。",
    "Use your knowledge of the earth to detect valuable gemstones by their resonance.": "利用你的大地知识，通过共振来探测有价值的宝石。",
    "Use your life force to produce a beneficial aura, mending the wounds and spirits of your allies.": "使用你的生命力产生有益光环，修复你盟友的伤口和精神。",
    "Use your new magics to furtively poke and pry into people's private affairs.": "用你的新魔法偷偷窥探和刺探人们的私事。",
    "Utilising the cooling properties of water and air mana, ensure a comfortable temperature across every nook and cranny of your residence.": "利用流水和大气法力的冷却特性，确保你住所的每个角落都保持舒适的温度。",
    "Various divine spirits watch over the world. And the greatest have their halls and kingdoms.": "各种神圣的灵体守护着世界。其中最伟大的拥有自己的殿堂和王国。",
    "Vicious witch in the waters of the Great Bog.": "大沼泽水域中的恶毒女巫。",
