    "Hidden Chamber": "隐藏室",
    "hidden chamber": "隐藏室",
    "If you did any of the tasks named: Decent/Immoral, Respectable/Wicked, or Virtuous/Vile, then you need to also do the one separated by a slash (Immoral if you did Decent, etc). If you have none of them, you qualify already. You must be tier 0 or higher.": "如果你完成了任何名为：体面/不道德、可敬/邪恶、或有德/卑劣的任务，那么你还需要完成斜线分隔的另一项（如果你做了体面，就做不道德，以此类推）。如果你一个都没有，你已经合格了。你必须达到 0 阶或更高。",
    "Imbuement Chambers": "灌注室",
    "imbuement chambers": "灌注室",
    "Inspiration struck and you devised a more elaborate loom, enchanted to weave ink and paper instead of thread.": "灵感来了，你设计了一台更精巧的织机，附魔用墨水和纸代替线编织。",
    "Iron Chest": "铁箱",
