    "You feel a brief flash of nostalgia for your days in the stable. Things were so much simpler back then... and they smelt like a stable, come to think of it. Life's better now.": "你对在马厩里的日子感到一阵短暂的怀念。那时的事情简单多了……而且说起来，确实有马厩的味道。现在的生活好多了。",
    "You must not be considered Respectable or Wicked, and your Virtue and Evil must be below 200 each. You must be tier 3 or higher.": "你不能被认为是可敬或邪恶的，你的美德和邪恶必须各低于 200。你必须达到 3 阶或更高。",

    // -------- 技能 (170条) --------
    "A brightly-colored cap jingling cheerfully as you go.": "一顶色彩鲜艳的帽子，走动时欢快地叮当作响。",
    "A brightly-colored tunic in an eyetwisting pattern.": "一件图案令人眼花缭乱的鲜艳上衣。",
    "A cache of treasure buried in the ground, protected by enchantment.": "埋藏在地下的宝藏，受附魔保护。",
