    "A worrying rumble from your enchanted study is quickly followed by a localized dimensional collapse. You now seem to only have a single study. At least it seems better than before.": "你的附魔书房传来令人担忧的轰鸣声，随后发生了局部维度崩塌。你现在似乎只有一个书房了。至少它看起来比以前好了。",
    "Activate your enchanted scriptorium, making scroll scribing a sustained action.": "激活你的魔法缮写室，使卷轴抄写成为持续行动。",
