    "Explore Reedburgh Markets. You will need a Reedburgh City Pass to be allowed entry, which requires the City Navigation skill.": "探索 Reedburgh 市场。你需要 Reedburgh 城市通行证才能进入，这需要城市导航技能。",
    "Explore the connections between this plane and the others.": "探索这个位面与其他位面之间的联系。",
    "Explore Treffil Wood": "探索特雷菲尔森林",
    "Folklore has it old enough tools come to life and seek blood. You plan to live long enough that taming your tools ahead of time is the best option.": "民间传说称足够古老的工具会活过来并寻求鲜血。你计划活得足够长，提前驯服你的工具是最好的选择。",
    "forge enchantments": "锻造附魔",
    "Forsaking war and violence, Bloodbane devoted himself to crafting new forms of magic.": "弃战乱杀伐于不顾，血厄尊者潜心开创全新魔法体系。",
    "Further hidden meanings lie beneath a magical text's surface, enchant your grimoires to decode these arcane ciphers.": "魔法文本表面之下隐藏着更深的含义，附魔你的魔法书以解码这些奥术密码。",
