    "More accurately a set of potions, designed to induce rapid heat loss in the affected subject.": "更准确地说是一套药剂，旨在使受影响对象快速失热。",
    "Most mages just treat runic enchantments as a tedious, if effective endeavor. Why bother finding out why it works, if you can just repeat the patterns from a book?": "大多数法师只是将符文附魔视为繁琐但有效的工作。既然可以照本宣科，何必探究其原理？",
    "Must live outdoors and be capable of enchanting.": "必须居住在户外并能够附魔。",
