    "The finest tools for crafting runes, reinvented after you discovered the secrets of lost Orrem.": "制作符文的最精良工具，在你发现了失落的奥雷姆的秘密后重新发明。",
    "The pinnacle of the crafting/animation arts, this skill represents the capacity to create artificial life.": "制作/活化艺术的顶峰，这个技能代表着创造人工生命的能力。",
    "The workshop of the legendary alchemist said to have come closest to crafting the philosopher's stone. Despite having degraded, you can still glean a great deal of wisdom from Fazbit's experiments.": "传说中最接近炼制贤者之石的传奇炼金术士的作坊。尽管已经破败，你仍然可以从法兹比特的实验中获得大量智慧。",
    "These enchanted woods are not particularly dangerous.": "这片附魔林地并不算凶险莫测。",
    "Unlocks advanced items for crafting.": "解锁高级可制作物品。",
