    "Unlocks expert items for crafting.": "解锁专家级可制作物品。",
    "Unlocks expert materials for crafting.": "解锁专家级锻造材料。",
    "Using your arcane powers, enchant the texts populating your study's shelves to whisper their hidden wisdoms.": "使用你的奥术力量，附魔书房书架上的文本，让它们低语隐藏的智慧。",
