    "World Lore: Mastery": "世界学识：掌握",
    "You explored further from civilisation than most commoners would dare. You are going to need magic to survive even more dangerous environments.": "你探索到了比大多数凡人敢去的更远的地方。你需要魔法才能在更危险的环境中生存。",
    "You need to be tier 4 and posess expertise in alchemy to be able to control this kind of body. You also must investigate Mount Gorborung.": "你需要达到4阶并拥有炼金术专精才能控制这种身体。你还必须调查戈博隆山。",
    "➢ The 'Crafting: Arms of Iron' unlocks the Crafting Tab.": "➢ 「制作：钢铁武备」解锁制作标签。",

    // -------- 资源 (357条) --------
    "A box carved from idrasil to hold the most potent runes.": "用伊德拉希尔木雕刻的箱子，用于存放最强大的符文。",
    "A complex alchemical process drips arcane energy onto gemstones.": "一套繁复的炼金工序，将奥术能量缓缓灌注于宝石之上。",
    "A comprehensive catalog of Dhrune's greatest history and achievements. A target for you to surpass.": "德鲁恩伟大历史与成就的综合目录。一个你要超越的目标。",
    "A comprehensive work on Dhrune's history and achievements, large enough to fill a library.": "关于德鲁恩历史与成就的综合著作，大到足以填满一座图书馆。",
    "A crystal apparatus to siphon elemental energies into mana.": "一个用于将元素能量虹吸成魔力的水晶装置。",
    "A dusty codex from the Genezereth library.": "来自 Genezereth 图书馆的一本积灰的手抄本。",
    "A dwarf serves no tyrant. Should you descend into evil, these runecrafters would surely abandon you.": "矮人不侍暴君。若你堕入邪恶，这些符文工匠必会离你而去。",
    "A hefty tome of knowledge.": "厚重的学识典籍",
    "A niche dedicated to scrolls.": "一个专用于卷轴的角落。",
    "A novice can get by with very basic scrolls, hopefully you won't need any of the pricier ones.": "新手只用基础卷轴就能过渡，希望你无需用到高价卷轴。",
    "A pedestal for reading magic tomes. Improves study habits.": "用于阅读魔法典籍的基座。改善学习习惯。",
    "A Runestone carved in bone; it seems to whisper.": "刻在骨头上的符文石；它似乎在低语。",
    "A sack woven from living tissue helps preserve the gems.": "用活体组织编织的袋子有助于保存宝石。",
    "A Tattered Scroll": "破旧卷轴",
    "A tattered scroll": "破旧卷轴",
    "A weighty tome of knowledge.": "一本厚重的知识典籍。",
    "A wooden box brimming with tools for gathering and preserving herbs, flowers, and roots.": "一个装满用于采集和保存草药、花朵和根茎的工具的木盒。",
    "Activate your bindery, making codex binding a sustained action.": "激活你的装订室，使法典装订成为持续行动。",
    "Allows the user to become more vigorous over time.": "允许使用者随着时间的推移变得更加精力充沛。",
    "Amount of blood gems acquired is approximately 1 per 250 maximum hp an opponent had": "获得的血宝石数量大约为对手每250点最大生命值获得1颗",
    "An ancient rune engraved in unmelting ice": "一个刻在不融冰上的古老符文。",
