    "runic tome": "符文典籍",
    "Sacrifice the minion with proportionally the lowest current life to buff everyone else. It's fine, summons are just mana simulacra.": "按比例牺牲当前生命值最低的仆从来增强其他所有人。没关系，召唤物只是法力模拟体。",
    "Sacrifice the minion with the highest life to heal yourself. Remember, summons are merely mana simulacra.": "牺牲生命值最高的仆从来治疗自己。记住，召唤物只是法力模拟体。",
