    "Sell Tomes": "出售典籍",
    "Set your snow double to acquisition of cold hard gold": "将你的雪分身设置为获取冰冷的金币。",
    "Significantly increases the benefits of resting at the cost of gold": "显著增加休息的收益，但消耗金币",
    "sip of gold": "财富药剂",
    "Skeletal Runecarver": "骷髅符文雕刻者",
    "Small bag keeps gems safe without scratching.": "小袋子可安全存放宝石，防止刮擦。",
    "Some scrolls feel interminable.": "有些卷轴感觉永无止境。",
    "Some tomes are never finished.": "有些典籍永远写不完。",
    "Someone left a number of scrolls haphazardly strewn about.": "有人留下了一些卷轴，随意散得到处都是。",
    "Spin Gold": "纺金",
    "spin gold": "纺金",
    "spin gold✅": "点石成金✅",
    "Spin straw into gold.": "点草成金。",
    "stash of gold": "黄金储藏",
    "Stay hidden as you make copies of the tomes in the endless depths of the infinite library.": "在无限图书馆的无尽深处偷偷复制典籍。",
    "Study ancient Dhrunic runes.": "研究古老的 Dhrunic 符文。",
    "Study arcane scrolls.": "学习奥术卷轴。",
    "Study plants and herbs.": "研究植物与草药。",
    "studying scrolls": "学习卷轴",
    "studying scrolls ": "研读卷轴：",
    "Summon a rune of pure suffering. Its dark power doesn't distinguish between friend and foe.": "召唤一个纯粹痛苦的符文。它的黑暗力量不区分友敌。",
    "Summon Rune Of Agony": "召唤苦痛符文",
    "summon rune of agony": "召唤苦痛符文",
    "t_runes": "符石",
    "Technical Adjustment To Max Mana For Reasons": "技术性调整最大法力值",
    "Technical adjustment to max mana for reasons": "技术性调整最大法力值",
    "Technology too new to have a guild monopoly! Perfect for those pesky runes.": "技术太新，还没有行会垄断！非常适合那些烦人的符文。",
    "The most intricate one yet. Shuttles clack as it binds codices into tomes.": "迄今最复杂的一台。梭子咔嗒作响，将典籍装订成册。",
    "The shapeshifter's laboratory yields a clue as to how he managed to perform his transformations. You could make use of it yourself, if you so desire.": "变形者的实验室提供了一条关于他如何实现变形的线索。如果你愿意，你可以自己利用它。",
    "The space where a gem once was.": "曾经有一颗宝石的地方。",
    "The surging energy of this rune can be felt even by the least talented of mages.": "即使是最无天赋的法师也能感受到这枚符文中涌动的能量。",
    "The various prismatic magics develop from raw mana taking to natural phenomena. Channel them all within your body to further your research.": "各种棱彩魔法从原始魔力发展到自然现象。在体内引导它们以推进你的研究。",
    "There was a GEM here. It's gone now.": "这里曾经有颗宝石。现在它不在了。",
    "Third of the Four Weirs of Dhrune.": "德伦四大堰坝之第三堰。",
    "This alchemical apparatus seems to have been intended to transmute lead into gold.": "这个炼金装置似乎旨在将铅转化为金。",
    "Though neither a mage, nor a warrior, few braved the wilds of inner-Dhrune so completely as Tenwick.": "既非法师也非战士，但很少有人像坦威克那样完整地穿越过德鲁恩内境的荒野。",
    "Time flows along the grooves of the rune.": "时间沿着符文的凹槽流淌。",
    "Time Gem": "时间宝石",
    "time gem": "时间宝石",
    "Time Gem Rate: ": "时间宝石速率：",
    "Time Runes": "时间符文",
    "time runes": "时间符文",
    "Time Runes Rate: ": "时间符文速率：",
    "Tome Familiar": "典籍魔宠",
    "tome familiar": "典籍魔宠",
    "Tomes": "典籍",
    "tomes": "典籍",
    "Tomes Rate: ": "典籍速率：",
    "transfer gold": "转移金币",
    "Turns out mana really does grow on trees.": "原来魔力真的是从树上长出来的。",
    "Unburden your opponent of excess gold, valuable pieces of anatomy and other materials of use to an enterprising wizard.": "减轻对手的多余金币、有价值的解剖结构和其他对进取法师有用的材料。",
    "Unending Codex": "无尽法典",
    "unending codex": "无尽法典",
    "Unending Scroll": "无尽卷轴",
    "unending scroll": "无尽卷轴",
    "Unending Tome": "无尽典籍",
    "unending tome": "无尽典籍",
    "Unlocks abilities to scribe scrolls and bind codices as continuous actions. Activate via furniture.": "解锁持续抄写卷轴和装订典籍的能力。通过家具激活。",
    "Unlocks an ability to imbue gems as a continuous action. Activate via furniture.": "解锁持续灌注宝石的能力。通过家具激活。",
    "Unmistakably a rune, even if it's impossible to tell quite what it looks like.": "无疑是一枚符文，尽管无法确切说出它看起来像什么。",
    "Unspin Gold": "解纺金线",
    "unspin gold": "解纺金线",
    "Unusually, prepared by baking special herbs into a brownie.": "这些草药居然能用来做巧克力蛋糕",
    "Use your powers to cajole, coerce, and cudgel gold from the pockets of civilians.": "运用自身能力哄诱、胁迫、强取平民钱财。",
    "Useful for grinding herbs & fine ingredients.": "用于研磨草药和精细材料。",
    "Various fine gemstones.": "各种精美的宝石。",
    "Veldran never did manage to carve a kingdom from the wreck of Bodias' reign. But he did accrue a sizeable hoard.": "维尔德兰始终未能从波迪亚斯王朝的废墟中开辟出属于自己的王国，却积攒下了一笔数额庞大的宝藏珍藏。",
    "Vi": "毒",
    "vi": "毒",
    "Vigor": "活力",
    "vigor": "活力",
    "Vigor Rate: ": "活力速率：",
    "Violently expells all mana from user's body for a time.": "在一段时间内猛烈地将使用者体内所有魔力排出。",
    "Well Of Mana": "法力井",
    "well of mana": "法力井",
    "Where do they find the gemstones?": "他们从哪里找到宝石的？",
    "With the basement cleared your master will have more room to stash all the gold you've been earning.": "地窖清理干净后，你的导师将有更多空间来藏匿你赚来的所有金币。",
    "With your newfound lack of scruples, the skeletal runecarvers take their place in your workshops once again.": "随着你新获得的无耻，骷髅符文雕刻师再次在你的工坊中各就各位。",
    "You buy a strange scroll from a travelling peddler. If you could only decipher the cryptic symbols.": "你从流浪商人手中买下一卷神秘卷轴，唯独无法解读上面晦涩的符文。",
    "You have no need of these dry tomes and musty old books.": "你不需要那些枯燥的典籍和发霉的古书。",
    "You need to have 15 more runestones than the last time you took this upgrade, starting at 15 and ending at 75.": "你需要比上次购买此升级时多15个符文石，从15开始，到75结束。",
    "Your experimental ventures seem to be costing ever-increasing amounts of gold. You will need to look at methods to finance further research.": "你的实验性尝试似乎在花费越来越多的金币。你需要寻找方法为进一步研究提供资金。",
    "Your familiar is a kobold, greedy for gold.": "你的魔宠是一只狗头人，贪图黄金。",
    "Your familiar is an animated tome, filled with arcane knowledge and a thirst for expansion.": "你的魔宠是一本活化典籍，充满了奥术知识和扩张的渴望。",
    "➢ Focus consumes mana to grant skill experience.": "➢ 专注消耗法力来提供技能经验。",
    "➢ You've managed to reduce your maximum life to zero through penalties!": "➢ 你通过惩罚将最大生命值降低到了零！",

