    "Pouch": "小袋子",
    "pouch merchant": "袋子商人",
    "Prepare a rite for summoning a familiar. The exact shape will be chosen after the fact.": "准备一个召唤魔宠的仪式。具体形态将在之后选择。",
    "Rocks and sand form patterns of intricate design.": "岩石和沙子形成复杂设计的图案。",
    "Roll-over Item and hold {Shift} + {Number} to assign quickslot.": "鼠标悬停物品并按住Shift+数字键，可设置快捷栏",
    "sand bag": "沙袋",
    "Satyrs dispense with lower body accoutrements as well as all forms of headwear in favor of horns and horseshoes. They are much luckier than normal": "萨提尔不穿下半身服装也不戴任何头饰，取而代之的是角和马蹄铁。他们比常人幸运得多。",
    "Seems a tad pricey for a bag.": "这个背包定价略显偏高。",
    "So this is where everybody gets sent to.": "原来所有人都会被送到这里。",
    "Somber Candle": "幽暗蜡烛",
    "somber candle": "幽暗蜡烛",
    "Summon Familiar": "召唤魔宠",
    "summon familiar": "召唤魔宠",
    "Train your body to heal on its own.": "训练你的身体自行愈合。",
