    "velvet bag": "天鹅绒袋",
    "Wax Candle": "蜡烛",
    "wax candle": "蜡烛",
    "Weapon Designs": "武器设计",
    "White glowing candle.": "白色发光蜡烛。",
    "Who prices these bags?!": "谁给这些袋子定的价？！",
    "Wind Sign": "风息印记",
    "wind sign": "风息印记",
    "withered designs": "枯萎的设计图",
    "You no take candle!": "不准拿蜡烛！",
    "You'll make your own bags, thank you.": "你会自己做袋子，谢谢你。",
    "Your body of work has grown so voluminous it now needs to be stored in a great library.": "你的著作卷册如此庞大，现在需要存放在一个大图书馆中。",
    "Your familiar is a cat, as dark as the night that spawned him.": "你的魔宠是一只猫，如同孕育它的黑夜般黑暗。",
    "Your familiar is an imp, devious and prone to mischief.": "你的魔宠是一只小恶魔，狡猾且爱恶作剧。",
    "Your familiar is an owl, most active at night, just like you are.": "你的魔宠是一只猫头鹰，夜间最为活跃，就像你一样。",
    "Your master was a fool. A quick murder in the dark put an end to their petty demands, and frees you to pursue your own grander designs.": "你的主人是个蠢货。黑暗中一场干脆的谋杀终结了他琐碎的要求，让你得以追求自己更宏伟的计划。",
    "➢ Most sources of damage are assigned a damage type as can be seen in their tooltip.": "➢ 大多数伤害来源都被分配了伤害类型，可以在其工具提示中看到。",
    "➢ Running tasks priority can be further modified by assigning them as (G)oals or (H)obbies.": "➢ 运行中的任务优先级可以通过将其分配为(G)目标或(H)爱好来进一步调整。",

