    "In combat, summon a frost giant to fight for you.": "在战斗中，召唤一个霜巨人为你而战。",
    "In combat, summon a hobgoblin to fight for you.": "在战斗中，召唤一只熊地精为你而战。",
    "In combat, summon a phoenix egg which you must guard until it hatches.": "战斗中召唤一个你必须守护到孵化的凤凰蛋。",
    "In combat, summon a phoenix to fight for you.": "在战斗中，召唤一只凤凰为你而战。",
    "In combat, summon a really angry bee to fight for you.": "在战斗中，召唤一只非常愤怒的蜜蜂为你而战。",
    "In combat, summon a sand mite to fight for you.": "在战斗中，召唤一只沙螨为你而战。",
    "In combat, summon an ancestral hero to defend you.": "在战斗中，召唤一位先祖英雄来守护你。",
    "In combat, summon an arcane serpent to fight for you.": "在战斗中，召唤一条奥术蛇为你而战。",
    "In combat, summon an unicorn to fight for you.": "在战斗中，召唤一只独角兽为你而战。",
    "In the midst of a wide desolation, a tall grey-skinned creature with no eyes offers you its wares.": "在广阔的荒凉之中，一个高大的灰色皮肤没有眼睛的生物向你提供它的货物。",
