    "The blistering sands peel away your skin.": "炙热的沙子剥去你的皮肤。",
    "The man turns to face you, except instead of a face he simply has a patch of smooth, featureless skin.": "那个男人转身面向你，但代替脸的只是一块光滑、毫无特征的皮肤。",
