    "true strike": "真实打击",
    "Use your Snow Double as an extension of yourself, without tasking it otherwise": "将你的雪分身用作自身的延伸，无需其他指派。",
    "When summoned in combat": "在战斗中召唤时",
    "You need at least one whole star shard to study, despite how odd asking for a whole shard sounds.": "你至少需要一整块星陨碎片才能进行研究，尽管要求一整块碎片听起来很奇怪。",
    "Your master lies dead.  Now your journey to true power begins.  Best leave before people start asking questions...": "你的主人已死。现在，通往真正力量的旅程开始了。最好在有人起疑前离开……",
    "Your skin becomes adamant.": "你的皮肤变得坚不可摧。",
    "➢ Summons are temporary monsters which assist you in combat.": "➢ 召唤物是在战斗中协助你的临时怪物。",
    "➢ Unlike summons, minions persist between explorations and last as long as they have life.": "➢ 与召唤物不同，仆从在探索之间持续存在，只要他们有生命就能存活。",

    // -------- 怪物 (151条) --------
    "A champion among orcs.": "兽人中的冠军。",
    "A cross between a worm and a dragon.": "蠕虫和龙的杂交。",
