    "A shrine to divine forces.": "供奉神圣力量的神殿。",
    "A stronghold to defend you from the petty forces of the world.": "一座保护你免受世间琐碎力量侵扰的堡垒。",
    "A wizard's hall is where the mightiest mages gather, exchanging the most guarded of secrets amongst each other. Truly unstoppable as a combined force.": "法师大厅是最强大的法师聚集的地方，彼此交换最严守的秘密。作为联合力量真正不可阻挡。",
