    "Tiny vicious humanoid riding a dragonfly.": "骑着蜻蜓的微型凶残人形生物。",
    "What he lacked in depth, Karnivex made up for with sheer destructive force.": "Karnivex 在深度上有所欠缺，但用纯粹的破坏力弥补了。",
