    "You can't tell if she looks hungry. Or what a spider the size of a dog would eat.": "你看不出她是否饿了。或者狗那么大的蜘蛛会吃什么。",
    "You have slain a dragon and all you got was a lousy t-shirt!": "你屠了一条龙，就只得到一件破 T 恤！",
    "➢ Tasks which consume an action slot will attempt to perpetually perform themselves ad infinitum however, what happens when one such task can no longer be sustained?\n\n➢ Waiting Tasks refer to those tasks which were forced out of your action slot. They will attempt to take up your action whenever a vacancy is created.\n\n➢ The total number of Waiting Tasks you can have is defined by your total number of action slots + 5. Any further additions to the list will cause an older waiting task to be pushed out.\n\n➢ You can see your Waiting Tasks in the Activities popup menu which is the rightmost button above your actions.": "➢ 消耗行动槽位的任务会尝试无限地自行持续执行，但当这样的任务无法再维持时会发生什么？\\n\\n➢ 待执行任务指的是那些被强制移出行动槽位的任务。它们会在有空位时尝试重新占据你的行动槽位。\\n\\n➢ 你最多可拥有的待执行任务数量由你的行动槽位总数 + 5 决定。此后若再添加新任务，列表中最旧的待执行任务将被挤出。\\n\\n➢ 你可以在行动上方的最后一个按钮'活动'弹窗菜单中查看你的待执行任务。",

