    "'Dark and selfish deeds follow you, leaving a stain on your soul.'": "「黑暗与自私的行为跟随你，在你的灵魂上留下污点。」",
    "'To tame magical beasts you must begin with the ordinary', he says.": "'要驯服魔法兽，你必须从平凡开始，'他说道。",
    "'What did you do to Sandy Loam? Where is she?' 'Gone.'": "「你对 Sandy Loam 做了什么？她在哪？」「没了。」",
    "'What do you hear in the screams?' 'Truth.'": "「你在尖叫中听到了什么？」「真相。」",
    "'What do you see amidst the ashes?' 'Sprouts.'": "「你在灰烬中看到了什么？」「新芽。」",
    "'What do you see atop the world?' 'Completion.'": "「你在世界之巅看到了什么？」「圆满。」",
    "'What do you see in the abyss?' 'Perfection.'": "「你在深渊中看到了什么？」「完美。」",
    "'What do you see in the clouds?' 'Everything.'": "「你在云中看到了什么？」「一切。」",
    "'What do you see in the darkness?' 'Myself.'": "「你在黑暗中看到了什么？」「我自己。」",
    "'What do you see in the depths?' 'Potential.'": "「你在深处看到了什么？」「潜力。」",
    "'What do you see in the emptiness?' 'Clarity.'": "「你在虚空中看到了什么？」「清晰。」",
    "'What do you see in the next world?' '...'": "「你在下一个世界看到了什么？」「……」",
    "'What do you see in the winds?' 'Memories.'": "「你在风中看到了什么？」「记忆。」",
