    "An ancient artifact from before the art of Oneiromancy was lost. Makes users capable of controlling dreams... and vice-versa.": "一件源自解梦术失传前的古老神器，能让使用者掌控梦境……亦会被梦境反噬。",
    "An ancient crypt of crumbling stone.": "一座石体崩坏的古老陵窟。",
    "An ancient gryffon lives atop the Rithel's solitary turret, and Hettie spends her days grooming and feeding the beast.": "一只古老格里芬生活在 Rithel 的孤寂塔楼顶上，赫蒂每天梳理和喂养这头野兽。",
    "An ancient library at the bridge spanning Markhul's gap.": "横跨马尔库尔裂隙的石桥之上，矗立着一座古老藏书馆。",
    "An ancient, gnarled old tree stands here. You almost feel like it's watching you.": "一棵古老多节的老树站在这里。你几乎觉得它在看着你。",
    "An arid plain stretching across Arazor from the Arag Heights.": "一片干旱荒原，从阿拉格高地绵延至阿拉佐尔全境。",
    "An avian terror of mythic repute.": "神话声望的鸟类恐怖。",
    "An electric shock leaps from your fingers.": "一道电击从你的指尖跃出。",
    "An endless hole in the ground.": "地面上的无尽洞。",
    "An entire caravan of wagons banded together for safety and convenience.": "一整队篷车集结在一起，为了安全和便利。",
    "An eye for an eye.": "以眼还眼。",
    "An immortal knight of Dhroz. Of fifty slain, one is knighted.": "德罗兹的不朽骑士。每杀掉五十个，一个被册封。",
    "An impervious spire of metal and stone.": "一座坚不可摧的金属石塔。",
    "An incidental necessity to the advancement of magic.": "魔法进步的附带必需品。",
    "An intelligent scavenger with the features of a vulture.": "一个有秃鹫特征的智慧食腐者。",
    "An introduction to magical theory.": "魔法理论介绍。",
    "An island floating in an endless sky.": "漂浮在无尽天空中的岛屿。",
    "An old woman by the name of Berta tells you a story of how even after the miller died, the mill miracuously still works, even after several years of neglect.": "一位名叫贝尔塔的老妇人告诉你一个故事：即使磨坊主去世后，磨坊仍然奇迹般地运转，即使被忽视了好几年。",
    "An ordinary wizard's cap.": "一顶普通的巫师帽。",
    "An unnatural blend of serpent and rooster. As its stare is death, you avert your gaze as you approach.": "蛇和公鸡的非自然混合。由于它的凝视就是死亡，你在接近时移开你的目光。",
