    "Is he toying with you?": "他在耍你吗？",
    "It bears a striking similarity to the lesser mummers.": "它与次级哑剧演员有惊人的相似性。",
    "It blinked first.": "它先眨了眨眼。",
    "It burns.": "它在燃烧。",
    "It can't speak but likes it when you feed it oil.": "它不会说话，但喜欢你喂它油。",
    "It doesn't have a head. But you do.": "它没有头。但你有。",
    "It doesn't seem very nice.": "看起来不太友好。",
    "It is a rare opportunity to be able to fight one of the infamous Archlocks. Slay the greatest butcher of men in history who still stalks these lands.": "能够与臭名昭著的 Archlocks 之一战斗是一个稀有机会。杀死历史上仍然游荡在这片土地上的最伟大屠夫。",
    "It is said they feed on darkness.": "据说它们以黑暗为食。",
    "It is unclear if this was once a rat that was reshaped into a human, or a human twisted into a ratlike abomination. Either way, it bars your way forward": "不清楚这曾经是一只被改造成人的老鼠，还是一个人被扭曲成老鼠般的可憎之物。无论如何，它挡住了你前进的路。",
    "It is within a grand dream that an oneiromancer can do the impossible.": "在宏伟的梦境中，解梦师才能做到不可能之事。",
    "It just floats there...": "它就在那里漂浮……",
    "It just needs the aid of a knife and a few preservatives.": "只需要一把刀和一点防腐剂的帮助。",
    "It licks your brain with its mind.": "它用心灵舔你的大脑。",
    "It moves with heavy clonking steps.": "它用沉重哐当的脚步移动。",
    "It must have been a lot, a lot of wind": "一定是很多很多风",
    "It must have been the wind": "一定是风",
    "It occurs to you that you could make collecting faces so much quicker and easier.": "你意识到你可以让收集面孔变得更快更容易。",
    "It seeeeees you.": "它看~~~~到你。",
    "It seems to like rocks the best.": "它似乎最喜欢岩石。",
    "It vants to zuck your blood.": "它想吸你的血。",
    "It waits in time.": "它在时间中等待。",
    "It was a wizard, once.": "它曾是个巫师。",
    "It's always swordfish.": "总是剑鱼。",
    "It's big brain time.": "大脑全开时间。",
    "It's bitey.": "它喜欢咬东西。",
    "It's just you.": "只是你自己。",
    "Items Total:": "物品总计：",
