    "What a horrible night to have a curse.": "多么可怕的受诅咒之夜。",
    "What could go wrong?": "能出什么错呢？",
    "What is gone is gone.": "已逝去的就逝去了。",
    "What leads your way can lead to you.": "引领你道路的，也能引向你自身。",
    "What's so scary about a bunch of icicles?": "一堆冰锥有什么可怕的？",
    "What's so scary about a bunch of icicles? Well... this.": "一堆冰锥有什么可怕的？嗯……这个。",
