    "When in good moods, Titans sculpted mountains. In bad ones, nations became craters.": "心情好时，泰坦雕刻山脉。心情糟时，王国化为陨坑。",
    "When killed": "被击杀时",
    "When struck directly": "被直接击中时",
    "When target killed": "目标死亡时",
    "When Tenwick told Eledin the Ettinmoors couldn't be crossed in safety, the ranger picked up his bow and headed east.": "当坦威克告诉埃勒丁双头怪荒原无法安全穿越时，游侠拿起他的弓向东边去了。",
    "When the fetid barrows were discovered, dark acolytes gathered at the mounds seeking ancient patrons of their art.": "当恶臭古冢被发现时，黑暗的侍僧们聚集在土丘周围，寻求他们艺术的古老庇护者。",
    "When used": "效果",
    "Where Desilla's harem still lays together in happy union. Bring about an end to their insidious playtime.": "德西拉的后宫依旧在幸福的结合中相依相偎。终结他们阴险的游戏时间。",
    "While performing chores, something illustrious catches your eye. Sure of its worthlessness, you wonder about its composition.": "做杂务时，某种闪亮的东西吸引了你的注意。你确定它毫无价值，但对它的成分感到好奇。",
    "While preserving the specimens that passed away, you may as well study their insides.": "在保存逝去标本的同时，你不妨研究一下它们的内部构造。",
    "Whilst seeing your reflection, an understanding of flow and stagnation dawns.": "看着自己的倒影，你开始领悟流动与停滞的含义。",
    "Whirling Step": "回旋步",
    "whirling step": "回旋步",
    "Whispers on the wind calm your troubled mind.": "风中的低语安抚你困扰的心灵。",
