    "Why do they come to me to die?": "为什么他们来找我赴死？",
    "Why does Master charge so many fees?": "为什么师傅要收这么多费用？",
    "Why study when you can perform parlor tricks for coin?": "当你能靠戏法赚钱时，为什么还要学习？",
