    "yeti": "雪人",
    "yog-sothoth": "犹格·索托斯",
    "You almost wish to never wake up again.": "你几乎希望再也不要醒来。",
    "You are a master of your field of magic.": "你是你魔法领域的大师。",
    "You are sure that this is where Hank must be.": "你确信汉克一定在这里。",
    "You are turning out to be an upstanding spellcaster.": "你正在成为一个正直的施法者。",
    "You braved every blizzard and stayed cool throughout. Congratulations!": "你勇敢面对每一场暴风雪并始终保持冷静。恭喜！",
    "You can do anything!": "你无所不能！",
    "You can feel the chill spreading": "你能感觉到寒意正在蔓延。",
    "You can purchase this once per completion of 'Musty Library'.": "每次完成「发霉的图书馆」可购买一次。",
    "You can't escape the sky.": "你无法逃脱天空。",
    "You can't seem to pry it loose.": "你似乎无法把它撬松。",
    "You could bounce a coin off those abs.": "你可以在那些腹肌上弹硬币。",
    "You create your own luck.": "你创造自己的运气。",
    "You deserve better. It's time to restore your ruined castle to its past splendor.": "你值得更好的。是时候修复你的废墟城堡，恢复它昔日的辉煌了。",
    "You deserve better. It's time to restore your ruined palace to its past splendor.": "你值得更好的。是时候修复你的废墟宫殿，恢复它昔日的辉煌了。",
    "You don't get to learn what sounds a fox would make.": "你没机会知道狐狸会发出什么声音了。",
    "You don't see a thing.": "你什么都看不到。",
    "You feel drawn to its flickering flame.": "你被它摇曳的火焰所吸引。",
    "You feel like imbuing yourself with Ice can push your power even further.": "你觉得自己注入冰之力可以进一步推动你的力量。",
    "You gotta... dance.": "你得……跳舞。",
    "You have become a respected personage in the magical world.": "你已成为魔法界受人尊敬的人物。",
    "You have reason to suspect Hank is here. The ghost of the thief must have stolen him away to enact revenge.": "你有理由怀疑汉克在这里。盗贼的鬼魂一定把他偷走以实施报复。",
    "You have reason to suspect Hank is here. Why would he go that way though?": "你有理由怀疑汉克在这里。但他为什么要走那条路呢？",
    "You have survived the chilly winds and monsters of the white": "你在寒风和白色怪物的威胁下幸存了下来。",
    "You have taken your first steps on the path of evil. It's a good thing.": "你已经在邪恶的道路上迈出了第一步。这是件好事。",
    "You hear a faint moaning, but are unable to determine its source.": "你听到微弱的呻吟，但无法确定其来源。",
    "You need a starsource and a workspace.": "你需要一个星源和一个工作区。",
    "You need that to live!": "你需要那个才能活命！",
    "You need to have taken classes tagged 'Master of Divination' at least as many times as you've done this task. It still maxes at 3.": "你需要参加过标记为占卜大师课程的次数至少与你完成此任务的次数相同。它仍然最多 3 次。",
    "You remind me of the babe.": "你让我想起那个婴儿。",
    "You rest in the shade amid flowers of heather.": "你在石楠花丛的树荫中休息。",
    "You see some undigested bones and jewels in its... 'belly'? Gross.": "你看到一些未消化的骨头和珠宝在它的……\\",
    "You see things before they happen.": "你在事情发生之前就已预见。",
    "You sense countless sprits beyond the gate.": "你感觉到门后有无数精灵。",
    "You sense something buried nearby.": "你感觉到附近埋着什么东西。",
    "You should have stayed out of the cloudspine.": "你本应该远离云脊山脉。",
    "You soon become lost in the false cooridors.": "你很快在虚假的走廊中迷失。",
    "You spotted a thief hideout nearby while exploring. It'd be wise to nip this threat in the bud before they learn of your wealth.": "你在探索时发现了附近的一个盗贼窝点。在他们了解到你的财富之前，将威胁扼杀在摇篮中是明智之举。",
    "You spread the joy of the cold far and wide, for the winter has come": "你将寒冷的喜悦传播到四面八方，因为冬天已经来临。",
    "You won't go down without a fight.": "你不会轻易倒下。",
    "You've learned better. Perfected the science. You can recreate yourself perfect and free of mankind's flaws.": "你学得更好了。完善了这门科学。你可以重塑自己，完美无缺，摆脱人类的缺陷。",
    "You've learned to swap bits between living and inanimate things.": "你学会了在生命和无生命事物之间交换碎片。",
    "You've never seen such bones before.": "你从未见过这样的骨头。",
    "You've seen bigger.": "你见过更大的。",
    "Your actions have shown you to be a virtuous wizard.": "你的行动表明你是一位有美德的巫师。",
    "Your barrier hardens till it's tougher than rocks.": "你的屏障硬化到比岩石更坚固。",
    "Your capacity for short-term exertions.": "短时间爆发负重与行动耐力上限。",
    "Your empire of dirt.": "你的尘土帝国。",
    "Your first attempt to raise a spire was rough. Refine its structure.": "你第一次升起尖塔的尝试很粗糙。改进它的结构。",
    "Your geomancy level must be higher than the amount of times you bought this upgrade. Gargoyles and grotesques are counted as 1 geomancy levels each for this requirement.": "你的地卜等级必须高于你购买此升级的次数。石像鬼和怪诞兽每个计为1地卜等级。",
    "Your inner fervour reaches a fever pitch, as uncontrolled as the dancing flame.": "你内心的热情达到狂热的高度，如同舞动的火焰般不受控制。",
    "Your magical might is deemed nearly inhuman, exceeding what is believed to be possible for a mortal to achieve.": "你的魔法力量被认为近乎非人，超越了凡人被认为能够达到的极限。",
    "Your map of the heavens is complete.": "你的天堂星图已完成。",
    "Your master behind you, you set off into the world alone. You had better find a new place to stay.": "告别了你的导师，你独自踏上旅途。最好找个新住处。",
    "Your master has decided you are ready to take the next step on the path of wizardry.": "你的师傅认定你已经准备好踏上魔法之路的下一步。",
    "Your master offers you an old glove. 'My falcons are used to this one, just don't let them get into the holes.'": "你的导师给了你一只旧手套。\\",
    "Your master offers you an old hammer. 'The first hammer I made myself. Its balance is awful, do be careful.'": "你的导师给了你一把旧锤子。\\",
    "Your new and improved tools should make your work a lot more efficient.": "你崭新且改进过的工具应该会让你的工作更高效。",
    "Your power is immeasurable, your veins suffused with cold. But something feels wrong. The warmth is gone.": "你的力量无可估量，你的血管中充满了冰冷。但有些地方不对劲。温暖已经消失。",
    "Your reputation in the world.": "你在世界上的声誉。",
    "ythogtha": "伊索格塔",
