    "Banquet Hall": "宴会厅",
    "banquet hall": "宴会厅",
    "Beneath the tallest idrasil a great menagerie thrives beneath a second sky.": "至高世界树的荫蔽之下，一方异兽秘境在第二层天穹下繁衍生息。",
    "Best not disturb it.": "最好别打扰它。",
    "bind spellbook": "绑定法术书",
    "Birds flit to and fro and small woodland animals scurry about in all directions, paying you no heed.": "鸟儿飞来飞去，小型林地动物向各个方向疾跑，不把你放在眼里。",
    "Blast all enemies with crystallized shards of magically charged blood.": "用魔法充能血液的结晶碎片冲击所有敌人。",
    "Blood drawn from its sharp blades are all the sustenance it requires.": "从其锋利的叶片上汲取的血液便是它所需的全部养分。",
    "blood manor": "鲜血庄园",
